import { NO_COPY_CLASS } from "@hunt/copy-to-clipboard";
import { PuzzleWithCutscene, useColorAssist } from "@hunt/puzzle-components";
import React from "react";

const DATA = [
  { numbers: "9 ? 1", className: "text-[#6fa8dc]", colorName: "blue" },
  { numbers: "3 ? 6", className: "text-[#ffd966]", colorName: "yellow" },
  { numbers: "2 ? 3", className: "text-[#93c47d]", colorName: "green" },
  { numbers: "3 ? 6", className: "text-[#e06666]", colorName: "red" },
];

const toClassName = (showColorName: boolean) => (showColorName ? "" : "hidden");

export const ColoredNumbers = () => {
  const [showColorName, setShowColorName] = useColorAssist();

  return (
    <>
      <PuzzleWithCutscene id="kc03" />
      {DATA.map((row, index) => {
        return (
          <div key={index}>
            <span className={row.className}>{row.numbers}</span>
            &nbsp;
            <span className={toClassName(showColorName)}>
              ({row.colorName})
            </span>
          </div>
        );
      })}
      {/* Checkbox to toggle the color name display */}
      <div className={"mt-4 flex justify-start " + NO_COPY_CLASS}>
        <label className="flex items-center space-x-2 cursor-pointer">
          <input
            type="checkbox"
            checked={showColorName}
            onChange={() => {
              setShowColorName(!showColorName);
            }}
            className="h-4 w-4 rounded border-gray-300"
            aria-label="Show color names alongside colored text"
          />
          <span>Show color names</span>
        </label>
      </div>
    </>
  );
};
